    }

    @Test
    void emptyFilterMatchesEveryCustomer() {
        assertEquals(500, repository.count(CustomerFilter.NONE));
    }

    @Test
    void nameTermsMatchRegardlessOfOrder() {
        CustomerFilter forward = new CustomerFilter("ada aal", Set.of());
        CustomerFilter backward = new CustomerFilter("aal ada", Set.of());

        List<Customer> forwardMatches = matching(forward);
        List<Customer> backwardMatches = matching(backward);

        assertEquals(forwardMatches.size(), backwardMatches.size());
        assertTrue(forwardMatches.stream()
                .anyMatch(c -> c.firstName().equals("Ada") && c.lastName().equals("Aaltonen")));
    }

    @Test
    void nameTermsThatDontShareACustomerMatchNobody() {
        assertEquals(0, matching(new CustomerFilter("ada virtanen", Set.of())).size());
    }

    @Test
    void nameMatchingIgnoresCaseAndAccents() {
        long expected = repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE, List.of(),
                new CustomerFilter("mäkinen", Set.of())).size();

        assertTrue(expected > 0);
        assertEquals(expected, matching(new CustomerFilter("makinen", Set.of())).size());
        assertEquals(expected, matching(new CustomerFilter("MAKINEN", Set.of())).size());

