+/**
+ * Narrows the customer list.
+ *
+ * @param name     free text; matches when every whitespace-separated term is a
+ *                 substring (case- and accent-insensitive) of the customer's
+ *                 first name or last name. Blank matches everyone.
+ * @param statuses statuses to include; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+}
