+        assertTrue(url.contains("status=ACTIVE,CLOSED") || url.contains("status=ACTIVE%2CCLOSED"),
+                "Expected status in declaration order in " + url);
+    }
+
+    @Test
+    void clearingTheFilterLeavesNoQueryParameters() {
+        TextField nameFilter = _get(TextField.class);
+        nameFilter.setValue("vir");
+        UI.getCurrent().getInternals().dumpPendingJavaScriptInvocations();
+
+        nameFilter.setValue("");
+
+        List<PendingJavaScriptInvocation> pending =
+                UI.getCurrent().getInternals().dumpPendingJavaScriptInvocations();
+        String url = pending.stream()
+                .filter(p -> p.getInvocation().getExpression().contains("replace: true"))
+                .reduce((first, second) -> second)
+                .map(p -> String.valueOf(p.getInvocation().getParameters().get(1)))
+                .orElseThrow(() -> new AssertionError("No replaceState call was made"));
+
+        assertFalse(url.contains("name="), "Expected no name parameter in " + url);
+        assertFalse(url.contains("status="), "Expected no status parameter in " + url);
+    }
 }
