--- /dev/null
+++ b/src/test/java/com/example/customers/domain/CustomerRepositoryFilterTest.java
@@ -0,0 +1,110 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+/**
+ * Direct, backend-only tests for the filtering added to {@link CustomerRepository}.
+ * No Spring context and no UI involved: these run in milliseconds.
+ */
+class CustomerRepositoryFilterTest {
+
+    private final QueryLog queryLog = new QueryLog();
+    private final CustomerRepository repository = new CustomerRepository(queryLog);
+
+    private List<Customer> matching(CustomerFilter filter) {
+        return repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE, List.of(), filter);
+    }
+
+    @Test
+    void emptyFilterMatchesEveryCustomer() {
+        assertEquals(500, repository.count(CustomerFilter.NONE));
+    }
+
+    @Test
+    void nameTermsMatchRegardlessOfOrder() {
+        CustomerFilter forward = new CustomerFilter("ada aal", Set.of());
+        CustomerFilter backward = new CustomerFilter("aal ada", Set.of());
+
+        List<Customer> forwardMatches = matching(forward);
+        List<Customer> backwardMatches = matching(backward);
+
+        assertEquals(forwardMatches.size(), backwardMatches.size());
+        assertTrue(forwardMatches.stream()
+                .anyMatch(c -> c.firstName().equals("Ada") && c.lastName().equals("Aaltonen")));
+    }
+
+    @Test
+    void nameTermsThatDontShareACustomerMatchNobody() {
+        assertEquals(0, matching(new CustomerFilter("ada virtanen", Set.of())).size());
+    }
+
+    @Test
+    void nameMatchingIgnoresCaseAndAccents() {
+        long expected = repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE, List.of(),
+                new CustomerFilter("mäkinen", Set.of())).size();
+
+        assertTrue(expected > 0);
+        assertEquals(expected, matching(new CustomerFilter("makinen", Set.of())).size());
+        assertEquals(expected, matching(new CustomerFilter("MAKINEN", Set.of())).size());
+
+        long josephineMatches = matching(new CustomerFilter("josephine", Set.of())).size();
+        assertTrue(josephineMatches > 0);
+        assertEquals(josephineMatches, matching(new CustomerFilter("joséphine", Set.of())).size());
+    }
+
+    @Test
+    void whitespaceAroundAndBetweenTermsIsNotSignificant() {
+        List<Customer> tidy = matching(new CustomerFilter("ada aal", Set.of()));
+        List<Customer> messy = matching(new CustomerFilter("   ada    aal   ", Set.of()));
+        assertEquals(tidy.size(), messy.size());
+    }
+
+    @Test
+    void statusFilterNarrowsToSelectedStatuses() {
+        List<Customer> activeOnly = matching(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)));
+        assertTrue(activeOnly.stream().allMatch(c -> c.status() == CustomerStatus.ACTIVE));
+        assertTrue(activeOnly.size() < 500 && activeOnly.size() > 0);
+
+        List<Customer> activeOrClosed = matching(
+                new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+        assertTrue(activeOrClosed.stream()
+                .allMatch(c -> c.status() == CustomerStatus.ACTIVE || c.status() == CustomerStatus.CLOSED));
+        assertTrue(activeOrClosed.size() > activeOnly.size());
+    }
+
+    @Test
+    void nameAndStatusFiltersBothApply() {
+        List<Customer> combined = matching(new CustomerFilter("aaltonen", Set.of(CustomerStatus.CLOSED)));
+        assertTrue(combined.stream().allMatch(
+                c -> c.lastName().equalsIgnoreCase("Aaltonen") && c.status() == CustomerStatus.CLOSED));
+        assertTrue(combined.size() > 0);
+    }
+
+    @Test
+    void pagingAndSortingApplyAfterFiltering() {
+        List<Customer> page = repository.findAll(0, 5, List.of(new CustomerSort("firstName", true)),
+                new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)));
+
+        assertEquals(5, page.size());
+        for (int i = 1; i < page.size(); i++) {
+            assertTrue(page.get(i - 1).firstName().compareToIgnoreCase(page.get(i).firstName()) <= 0);
+        }
+        page.forEach(c -> assertEquals(CustomerStatus.ACTIVE, c.status()));
+    }
+
+    @Test
+    void everyCallIsRecordedInQueryLog() {
+        queryLog.clear();
+        matching(new CustomerFilter("ada", Set.of()));
+        repository.count(new CustomerFilter("ada", Set.of()));
+
+        assertEquals(1, queryLog.pageQueries().size());
+        assertEquals(1, queryLog.countQueries().size());
+    }
+}
